/* Assignment 3: pure ANSI terminal rendering from one engine snapshot.
 * Floors are drawn top-down with lift occupancy, direction and waiting queues.
 * Load and wait colours make capacity and starvation visible at a glance.
 * The renderer never changes scheduling state and only the controller calls it. */
#include "core.h"
#include <stdio.h>
#include <sys/ioctl.h>
#include <unistd.h>

static const char*wait_colour(int w){return w<5?"\033[32m":w<15?"\033[33m":"\033[31m";}
void render_terminal(const Core*c,const Shared*s,int lazy){struct winsize ws={0};ioctl(STDOUT_FILENO,TIOCGWINSZ,&ws);printf("\033[H\033[J");if(ws.ws_col&&(ws.ws_col<80||ws.ws_row<28)){puts("Enlarge the terminal window to at least 80 x 28.");fflush(stdout);return;}Metrics m;core_metrics(c,&m);printf(" lift-os-sim | policy: %-18s | tick %-4d | delivered %d/%d\n",c->policy==POLICY_FCFS?"FCFS":"NEAREST-STOP-FIRST",c->tick,c->delivered,c->scenario.passenger_count);puts(" -------------------------------------------------------------------------------");for(int f=c->scenario.floors-1;f>=0;f--){printf(" F%-2d |",f);for(int k=0;k<c->scenario.lifts;k++){if(c->lift[k].floor==f){double ratio=(double)c->lift[k].riders/c->scenario.capacity;const char*col=ratio>=1?"\033[31m":ratio>=.7?"\033[33m":"\033[32m";char d=c->lift[k].direction>0?'^':c->lift[k].direction<0?'v':'-';printf(" %s[L%d %d/%d %c]\033[0m |",col,k,c->lift[k].riders,c->scenario.capacity,d);}else printf("             |");}printf(" waiting:");for(int i=0;i<c->scenario.passenger_count;i++){const CorePassenger*p=&c->passenger[i];if(p->state==WAITING&&p->from==f)printf(" %s%d\033[0m",wait_colour(c->tick-p->arrival),p->id);}putchar('\n');}puts(" -------------------------------------------------------------------------------");printf(" avg wait %.1f | avg load %.1f%% | empty moves %.1f%% | preempts %d | full %d\n",m.avg_wait,m.avg_load_pct,m.empty_move_pct,m.preempts,m.full_events);printf(" board reads %lu | writes %lu | corruption %lu\n",s?s->reads:0,s?s->writes:0,s?s->corrupt:0);printf(" events:");int from=c->event_count>3?c->event_count-3:0;for(int i=from;i<c->event_count;i++){const CoreEvent*e=&c->events[i];printf(" t%d %s",e->t,e->name);if(e->lift>=0)printf(" L%d",e->lift);if(e->passenger>=0)printf(" P%d",e->passenger);printf(" |");}putchar('\n');if(lazy)puts(" zombie demo: run  ps -el | grep defunct  in another terminal");fflush(stdout);}
